    Key? key,
    required this.label,
    this.hint,
    required this.icon,
    required this.value,
    required this.items,
    required this.onChanged,
    this.isLoading = false,
    this.emptyMessage = 'Tidak ada data ditemukan',
  }) : super(key: key);

  String get _selectedLabel {
    if (value == null) return hint ?? 'Pilih $label';
    final found = items.firstWhere(
      (item) => item.value == value,
      orElse: () => SearchableSelectItem(value: value as T, label: ''),
    );
    return found.label.isNotEmpty ? found.label : (hint ?? 'Pilih $label');
  }

  void _showSearchSheet(BuildContext context) {
    if (items.isEmpty && !isLoading) return;

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (ctx) => _SearchModalSheet<T>(
        title: label,
        icon: icon,
        items: items,
        selectedValue: value,
        emptyMessage: emptyMessage,
        onSelected: (val) {
          Navigator.pop(ctx);
          onChanged(val);
        },
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final hasValue = value != null;

    return Padding(
      padding: const EdgeInsets.only(bottom: 12.0),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          GestureDetector(
            onTap: isLoading ? null : () => _showSearchSheet(context),
            child: InputDecorator(
              decoration: InputDecoration(
                labelText: label,
                labelStyle: TextStyle(color: Colors.grey.shade600, fontSize: 14),
                filled: true,
                fillColor: const Color(0xFFF7F9FC),
                contentPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 16),
                prefixIcon: Icon(icon, color: hasValue ? AppConstants.primaryBlue : Colors.grey.shade500, size: 22),
                suffixIcon: isLoading
                    ? const SizedBox(
                        width: 20,
                        height: 20,
                        child: Center(
                          child: CircularProgressIndicator(strokeWidth: 2, color: AppConstants.primaryBlue),
                        ),
                      )
                    : Icon(Icons.arrow_drop_down_rounded, color: Colors.grey.shade600, size: 28),
                border: OutlineInputBorder(borderRadius: BorderRadius.circular(14), borderSide: BorderSide(color: Colors.grey.shade200)),
                enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(14), borderSide: BorderSide(color: Colors.grey.shade200)),
                focusedBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(14), borderSide: const BorderSide(color: AppConstants.primaryBlue, width: 2)),
              ),
              child: Text(
                _selectedLabel,
                style: TextStyle(
                  fontSize: 14,
                  fontWeight: hasValue ? FontWeight.w600 : FontWeight.normal,
                  color: hasValue ? AppConstants.textDark : Colors.grey.shade400,
