class _SearchModalSheetState<T> extends State<_SearchModalSheet<T>> {
  final TextEditingController _searchController = TextEditingController();
  List<SearchableSelectItem<T>> _filteredItems = [];

  @override
  void initState() {
    super.initState();
    _filteredItems = widget.items;
  }

  void _onSearchChanged(String query) {
    final cleanQuery = query.toLowerCase().trim();
    setState(() {
      if (cleanQuery.isEmpty) {
        _filteredItems = widget.items;
      } else {
        _filteredItems = widget.items.where((item) {
          final labelMatches = item.label.toLowerCase().contains(cleanQuery);
          final subtitleMatches = item.subtitle?.toLowerCase().contains(cleanQuery) ?? false;
          return labelMatches || subtitleMatches;
        }).toList();
      }
    });
  }

